/// <summary>
/// find last created record by item rec id
/// </summary>
/// <param name = "_inventTableRefRecId">Rec Id of invent table record</param>
/// <param name = "_lastDateTime">upper limit dateTime</param>
/// <param name = "_forupdate">for update</param>
/// <returns>NDXHK2MGKHistory record</returns>
public static NDXHK2MGKHistory findLast(RefRecId _inventTableRefRecId, utcdatetime _lastDateTime = DateTimeUtil::minValue(), boolean _forupdate = false)
{
    NDXHK2MGKHistory lNDXHK2MGKHistory;

    lNDXHK2MGKHistory.selectForUpdate(_forupdate);

    if(_lastDateTime > DateTimeUtil::minValue())
    {
        select firstonly lNDXHK2MGKHistory order by lNDXHK2MGKHistory.CreatedDateTime desc
            where lNDXHK2MGKHistory.InventTableRefRecId == _inventTableRefRecId
            && lNDXHK2MGKHistory.CreatedDateTime <= _lastDateTime;
    }
    else
    {
        select firstonly lNDXHK2MGKHistory order by lNDXHK2MGKHistory.CreatedDateTime desc
            where lNDXHK2MGKHistory.InventTableRefRecId == _inventTableRefRecId;
    }

    return lNDXHK2MGKHistory;
}

/// <summary>
/// Inserts history records for all items with the same HK2 group id 
/// </summary>
/// <param name = "_hk2FactorGroup">KCS_HK2FactorGroup record</param>
public static void createByKCS_HK2FactorGroup(KCS_HK2FactorGroup _hk2FactorGroup)
{
    NDXHK2MGKHistory lNDXHK2MGKHistory;
    InventTable lInvantTable;
    InventTableModule lInventTableModule;

    KCS_HK2GroupId groupId = _hk2FactorGroup.HK2GroupId;
    KCS_HK2Factor factor = _hk2FactorGroup.HK2Factor;
    NDXHK2GroupIdFromDate fromdate = _hk2FactorGroup.FromDate;

    AVAMGKFactors lAVAMGKFactors;

    insert_recordset lNDXHK2MGKHistory(InventTableRefRecId, HK2GroupId, HK2Factor, HK2FromDate, MGKGroupId, MGKFactor)
        select RecId, groupId, factor, fromdate from lInvantTable
            where lInvantTable.NDXHK2GroupRefRecId == _hk2FactorGroup.RecId
        join lInventTableModule
            where lInventTableModule.ItemId == lInvantTable.ItemId
                && lInventTableModule.ModuleType == ModuleInventPurchSales::Invent
        outer join MGKGroup, MGKFactor from lAVAMGKFactors
            where lAVAMGKFactors.RecId == lInventTableModule.NDXMGKGroupRefRecId;
}

/// <summary>
/// Inserts history records for all items with the same MGK group id
/// </summary>
/// <param name = "_AVAMGKFactors">AVAMGKFactors record</param>
public static void createByAVAMGKFactors(AVAMGKFactors _AVAMGKFactors)
{
    NDXHK2MGKHistory lNDXHK2MGKHistory;
    InventTable lInvantTable;
    InventTableModule lInventTableModule;

    AVAMGKGroup groupId = _AVAMGKFactors.MGKGroup;
    AVAMGKFactor factor = _AVAMGKFactors.MGKFactor;

    KCS_HK2FactorGroup lKCS_HK2FactorGroup;

    insert_recordset lNDXHK2MGKHistory(InventTableRefRecId, HK2GroupId, HK2Factor, HK2FromDate, MGKGroupId, MGKFactor)
        select RecId from lInvantTable
            outer join HK2GroupId, HK2Factor, FromDate from lKCS_HK2FactorGroup
                where lKCS_HK2FactorGroup.RecId == lInvantTable.NDXHK2GroupRefRecId
            join groupId, factor from lInventTableModule
                where lInventTableModule.ItemId == lInvantTable.ItemId
                    && lInventTableModule.ModuleType == ModuleInventPurchSales::Invent
                    && lInventTableModule.NDXMGKGroupRefRecId == _AVAMGKFactors.RecId;

}

/// <summary>
/// Create History by InventTableModule
/// </summary>
/// <param name = "_inventTableModule">InventtableModule record</param>
public static void createByInventTableModule(InventTableModule _inventTableModule)
{
    InventTable inventTable = InventTable::find(_inventTableModule.ItemId);

    NDXHK2MGKHistory lNDXHK2MGKHistory = NDXHK2MGKHistory::findLast(inventTable.RecId, DateTimeUtil::minValue());

    KCS_HK2FactorGroup lKCS_HK2FactorGroup = KCS_HK2FactorGroup::findByRecId(inventTable.NDXHK2GroupRefRecId);
    AVAMGKFactors lAVAMGKFactors = AVAMGKFactors::findByRecId(_inventTableModule.NDXMGKGroupRefRecId);

    NDXHK2MGKHistory newHistoryRecord;

    //the HK2 of MGK group changed
    if(lNDXHK2MGKHistory.HK2GroupId != lKCS_HK2FactorGroup.HK2GroupId
        || lNDXHK2MGKHistory.MGKGroupId != lAVAMGKFactors.MGKGroup)
    {   
        newHistoryRecord.InventTableRefRecId = inventTable.RecId;
        newHistoryRecord.HK2GroupId = lKCS_HK2FactorGroup.HK2GroupId;
        newHistoryRecord.HK2Factor = lKCS_HK2FactorGroup.HK2Factor;
        newHistoryRecord.HK2FromDate = lKCS_HK2FactorGroup.FromDate;

        newHistoryRecord.MGKGroupId = lAVAMGKFactors.MGKGroup;
        newHistoryRecord.MGKFactor = lAVAMGKFactors.MGKFactor;

        newHistoryRecord.insert();
    }
}

/// <summary>
/// Create History by InventTable
/// </summary>
/// <param name = "_inventTable">InventTable record</param>
public static void createByInventTable(InventTable _inventTable)
{
    InventTableModule lInventTableModule = InventTableModule::find(_inventTable.ItemId, ModuleInventPurchSales::Invent);
    NDXHK2MGKHistory lNDXHK2MGKHistory = NDXHK2MGKHistory::findLast(_inventTable.RecId, DateTimeUtil::minValue());

    KCS_HK2FactorGroup lKCS_HK2FactorGroup = KCS_HK2FactorGroup::findByRecId(_inventTable.NDXHK2GroupRefRecId);
    AVAMGKFactors lAVAMGKFactors = AVAMGKFactors::findByRecId(lInventTableModule.NDXMGKGroupRefRecId);

    NDXHK2MGKHistory newHistoryRocord;

    //the HK2 of MGK group changed
    if(lNDXHK2MGKHistory.HK2GroupId != lKCS_HK2FactorGroup.HK2GroupId
        || lNDXHK2MGKHistory.MGKGroupId != lAVAMGKFactors.MGKGroup)
    {
        newHistoryRocord.InventTableRefRecId = _inventTable.RecId;
        newHistoryRocord.HK2GroupId = lKCS_HK2FactorGroup.HK2GroupId;
        newHistoryRocord.HK2Factor = lKCS_HK2FactorGroup.HK2Factor;
        newHistoryRocord.HK2FromDate = lKCS_HK2FactorGroup.FromDate;

        newHistoryRocord.MGKGroupId = lAVAMGKFactors.MGKGroup;
        newHistoryRocord.MGKFactor = lAVAMGKFactors.MGKFactor;

        newHistoryRocord.insert();
    }
}

