/// <summary>
/// Create record by history HK2 group
/// </summary>
/// <param name = "_ndxHK2GroupHistory">hk2 group history record</param>
public static void createByHK2GroupHistory(NDXHK2GroupHistory _ndxHK2GroupHistory)
{
    NDXHK2MGKHistory lNDXHK2MGKHistory;

    lNDXHK2MGKHistory.InventTableRefRecId = _ndxHK2GroupHistory.InventTableRefRecId;
    lNDXHK2MGKHistory.HK2GroupId = _ndxHK2GroupHistory.HK2GroupIdTo;
    lNDXHK2MGKHistory.HK2Factor = _ndxHK2GroupHistory.HK2FactorTo;

    lNDXHK2MGKHistory.insert();
}

