/// <summary>
/// Create by HK1 History record
/// </summary>
/// <param name = "_ndxHK1History">HK1 history record</param>
public static void createByHK1History(NDXHK1History _ndxHK1History)
{
    NDXHK2MGKHistory lNDXHK2MGKHistory;

    update_recordset lNDXHK2MGKHistory 
        setting 
            HK1HistoryRefRecId = _ndxHK1History.RecId
        where lNDXHK2MGKHistory.InventTableRefRecId == _ndxHK1History.InventTableRefRecId
            && lNDXHK2MGKHistory.HK1HistoryRefRecId == 0;
}

[SysClientCacheDataMethodAttribute(true)]
display NDXHK2MGKPrice dispHK2PriceTo()
{
    Price hk2Price = 0;
    Price hk1 = 0;

    if(!this.HK1HistoryRefRecId && this.InventTableRefRecId)
    {
        InventTable lInventTable = InventTable::findByRecId(this.InventTableRefRecId);
        InventTableModule lInventTableModule = InventTableModule::find(lInventTable.ItemId, ModuleInventPurchSales::Invent);

        hk1 = lInventTableModule.NDX_showHK1current();
    }
    else
    {
        NDXHK1History lNDXHK1History = NDXHK1History::find(this.HK1HistoryRefRecId);
        hk1 = lNDXHK1History.HK1From;
    }

    if(!NDXPrivilegeManagement::hasSecuritykeyAccess(privilegeStr(NDXHK1View)))
    {
        hk1 = 0;
    }

    if(NDXPrivilegeManagement::hasSecuritykeyAccess(privilegeStr(NDXHK2View)))
    {
        KCS_HK2Factor hk2Factor = this.HK2Factor;
        AVAMGKFactor mgkFactor = this.MGKFactor;

        if(this.HK2GroupId == '')
        {
            hk2Factor = 1;
        }

        if(this.MGKGroupId == '')
        {
            hk2Factor = 1;
        }

        hk2Price= hk1 * hk2Factor * mgkFactor;
    }

    return hk2Price;
}
